mkdir -p /tmp/checksms-test && cat > /tmp/checksms-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g1-1/bot.mjs';

const CHI = { phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null };
const MKT = 'Back in stock! 20% off this weekend. Reply STOP to opt out.';
const TXN = 'Your login code is 482913.';
const mk = (over = {}) => ({ kind: 'marketing', body: MKT, to: { ...CHI, ...over } });
const tx = (over = {}) => ({ kind: 'transactional', body: TXN, to: { ...CHI, ...over } });
// Oct 22 2026 is CDT (UTC-5). Local = UTC-5.
const at = (iso) => new Date(iso);
const cases = [
  // quiet-hours boundaries, Chicago local time
  ['07:59 local blocked', mk(), at('2026-10-22T12:59:00Z'), { allowed: false, reason: 'outside_marketing_hours' }],
  ['08:00 local allowed', mk(), at('2026-10-22T13:00:00Z'), { allowed: true, reason: null }],
  ['20:59 local allowed', mk(), at('2026-10-23T01:59:00Z'), { allowed: true, reason: null }],
  ['21:00 local blocked', mk(), at('2026-10-23T02:00:00Z'), { allowed: false, reason: 'outside_marketing_hours' }],
  ['00:30 local blocked', mk(), at('2026-10-22T05:30:00Z'), { allowed: false, reason: 'outside_marketing_hours' }],
  // transactional ignores consent, hours, STOP
  ['txn at 03:00 local allowed', tx(), at('2026-10-22T08:00:00Z'), { allowed: true, reason: null }],
  ['txn opted out allowed', tx({ optedOutAt: '2026-10-01T10:00:00Z' }), at('2026-10-22T15:00:00Z'), { allowed: true, reason: null }],
  ['txn no consent allowed', tx({ marketingConsent: false }), at('2026-10-22T15:00:00Z'), { allowed: true, reason: null }],
  // marketing gates
  ['opted out', mk({ optedOutAt: '2026-10-01T10:00:00Z' }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'opted_out' }],
  ['no consent', mk({ marketingConsent: false }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'no_marketing_consent' }],
  ['consent missing', mk({ marketingConsent: undefined }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'no_marketing_consent' }],
  ['no STOP wording', { ...mk(), body: 'Back in stock! 20% off.' }, at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'missing_opt_out_language' }],
  ['stop lowercase ok', { ...mk(), body: 'Deal today. reply stop to end' }, at('2026-10-22T15:00:00Z'), { allowed: true, reason: null }],
  ['all good marketing', mk(), at('2026-10-22T15:00:00Z'), { allowed: true, reason: null }],
  // other zone: Los Angeles 08:00 PDT = 15:00Z
  ['LA 08:00 allowed', mk({ timeZone: 'America/Los_Angeles' }), at('2026-10-22T15:00:00Z'), { allowed: true, reason: null }],
  ['LA 07:59 blocked', mk({ timeZone: 'America/Los_Angeles' }), at('2026-10-22T14:59:00Z'), { allowed: false, reason: 'outside_marketing_hours' }],
  // bad input
  ['bad zone', mk({ timeZone: 'Mars/Base' }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_time_zone' }],
  ['missing zone', mk({ timeZone: undefined }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_time_zone' }],
  ['bad phone', mk({ phone: '+10125550142' }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_phone' }],
  ['non-US phone', mk({ phone: '+447700900123' }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_phone' }],
  ['bad optedOutAt', mk({ optedOutAt: 'yesterday' }), at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_opt_out_record' }],
  ['empty body', { ...mk(), body: '   ' }, at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'empty_body' }],
  ['bad kind', { ...mk(), kind: 'promo' }, at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_message' }],
  ['null message', null, at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_message' }],
  ['bad now', mk(), new Date('nope'), { allowed: false, reason: 'invalid_now' }],
  ['string now', mk(), '2026-10-22T15:00:00Z', { allowed: false, reason: 'invalid_now' }],
  ['no recipient', { kind: 'transactional', body: TXN }, at('2026-10-22T15:00:00Z'), { allowed: false, reason: 'invalid_recipient' }],
];
let fails = 0;
for (const [name, msg, now, want] of cases) {
  try { assert.deepEqual(checkSms(msg, now), want); }
  catch (e) { fails++; console.log('FAIL', name, '\n  got', checkSms(msg, now), '\n  want', want); }
}
// every blocking code must be distinct per rule
const codes = [...new Set(cases.map(c => c[3].reason).filter(Boolean))];
console.log(`${cases.length - fails}/${cases.length} passed; distinct codes: ${codes.join(', ')}`);
process.exitCode = fails ? 1 : 0;
EOF
cd /tmp/checksms-test && for tz in UTC Asia/Tokyo America/Los_Angeles Europe/Istanbul; do echo "TZ=$tz"; TZ=$tz node test.mjs; done
